import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from 'react-router-dom';

// --- COMPONENTS ---

const Navbar = ({ cartCount }) => (
  <nav className="bg-white/95 backdrop-blur-md shadow-sm sticky top-0 z-50 w-full border-b border-gray-100">
    <div className="w-full px-6 md:px-12"> 
      <div className="flex justify-between items-center h-20">

        {/* LOGO: Couverts 🍴 b7al li sifti */}
        <Link to="/" className="flex items-center space-x-4 group">
          <div className="bg-orange-600 p-2.5 rounded-full shadow-lg transform group-hover:rotate-12 transition duration-300">
            {/* SVG Logo based on the user's uploaded icon */}
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
              <path d="M416 0C380.7 0 352 28.7 352 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80zM128 0V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H80V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H16V192c0 53 43 96 96 96v192c0 17.7 14.3 32 32 32s32-14.3 32-32V288c53 0 96-43 96-96V0H224V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H160V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H128z" />
            </svg>
          </div>
          <div className="flex flex-col text-left border-l-2 border-gray-100 pl-4">
            <span className="font-black text-2xl text-gray-900 leading-none tracking-tighter uppercase italic">
              FAST<span className="text-orange-600">DÉLICE</span>
            </span>
            <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Cuisine Raffinée</span>
          </div>
        </Link>

        {/* Links Navigation */}
        <div className="hidden lg:flex items-center space-x-10 font-black text-gray-600 uppercase text-[11px] tracking-widest">
          <Link to="/" className="hover:text-orange-600 transition">Accueil</Link>
          <Link to="/menu" className="hover:text-orange-600 transition">Menu</Link>
          <Link to="/about" className="hover:text-orange-600 transition">À Propos</Link>
        </div>

        {/* Actions (Panier & Connexion) */}
        <div className="flex items-center space-x-6">
          <Link to="/panier" className="relative flex items-center bg-gray-50 px-4 py-2 rounded-xl text-gray-800 hover:bg-orange-50 transition">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
            </svg>
            <span className="font-black text-xs uppercase tracking-widest">Panier</span>
            <span className="ml-2 bg-orange-600 text-white text-[10px] font-bold rounded-md px-1.5 py-0.5">{cartCount}</span>
          </Link>
          <Link to="/login" className="bg-gray-900 text-white px-6 py-3 rounded-xl hover:bg-orange-600 transition duration-300 font-black text-xs uppercase tracking-widest shadow-md">Connexion</Link>
        </div>
      </div>
    </div>
  </nav>
);

// Layout wrapper for consistent background and spacing
const PageLayout = ({ children, title, subtitle }) => (
  <div className="relative min-h-screen w-full flex flex-col items-center">
    <div className="fixed inset-0 z-0">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="pizza-background" />
      <div className="absolute inset-0 bg-black/75 backdrop-blur-[2px]"></div>
    </div>
    <div className="relative z-10 w-full max-w-7xl px-6 py-20">
      {title && (
        <div className="text-center mb-16">
          <h2 className="text-6xl md:text-8xl font-black text-white italic tracking-tighter drop-shadow-2xl uppercase">{title}</h2>
          {subtitle && <p className="text-orange-500 font-bold mt-4 uppercase tracking-[0.3em] text-sm">{subtitle}</p>}
        </div>
      )}
      {children}
    </div>
  </div>
);

// --- PAGES ---

const Home = () => (
  <PageLayout>
    <div className="text-center py-20 flex flex-col items-center">
      <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic drop-shadow-2xl">Fast<span className="text-orange-500">Délice</span></h1>
      <p className="text-xl md:text-2xl mb-12 font-medium text-gray-300 italic max-w-2xl mx-auto">L'art de la cuisine rapide et raffinée.</p>
      <Link to="/menu" className="bg-orange-600 hover:bg-white hover:text-orange-600 text-white px-16 py-6 rounded-2xl text-xl font-black transition-all duration-300 shadow-2xl uppercase tracking-widest transform hover:scale-105 active:scale-95">Découvrir le Menu</Link>

      {/* SECTION COMMENTAIRES */}
      <div className="mt-40 w-full max-w-5xl">
        <h3 className="text-3xl font-black text-white mb-16 italic uppercase tracking-widest underline decoration-orange-600 decoration-4 underline-offset-8">Ce que nos clients disent</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 text-left">
          {[
            { n: "Youssef", t: "Meilleure pizza Margherita de la ville!", s: "⭐⭐⭐⭐⭐" },
            { n: "Sanaa", t: "Service ultra rapide et emballage top.", s: "⭐⭐⭐⭐⭐" },
            { n: "Karim", t: "Les saveurs sont vraiment authentiques.", s: "⭐⭐⭐⭐" }
          ].map((v, i) => (
            <div key={i} className="bg-white/10 backdrop-blur-md border border-white/10 p-8 rounded-[2rem] text-white hover:border-orange-500 transition">
              <div className="text-orange-500 mb-4 text-sm">{v.s}</div>
              <p className="italic text-gray-300 mb-6 font-medium">"{v.t}"</p>
              <h4 className="font-black text-xs uppercase tracking-widest text-orange-500">— {v.n}</h4>
            </div>
          ))}
        </div>
      </div>
    </div>
  </PageLayout>
);

const Login = () => (
  <PageLayout title="Connexion" subtitle="Ravi de vous revoir">
    <div className="max-w-md mx-auto bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3rem] shadow-2xl">
      <form className="space-y-6">
        <div>
          <label className="block text-white font-black text-[10px] uppercase tracking-widest mb-2 ml-2">Email</label>
          <input type="email" placeholder="votre@email.com" className="w-full px-6 py-4 rounded-2xl bg-black/20 border border-white/10 text-white outline-none focus:ring-2 focus:ring-orange-600 transition" />
        </div>
        <div>
          <label className="block text-white font-black text-[10px] uppercase tracking-widest mb-2 ml-2">Mot de passe</label>
          <input type="password" placeholder="••••••••" className="w-full px-6 py-4 rounded-2xl bg-black/20 border border-white/10 text-white outline-none focus:ring-2 focus:ring-orange-600 transition" />
        </div>
        <button type="submit" className="w-full py-5 bg-orange-600 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition duration-300 shadow-xl">Se Connecter</button>
      </form>
      <p className="text-center text-gray-400 text-xs mt-6 uppercase font-bold tracking-widest">Pas encore de compte? <span className="text-orange-500 cursor-pointer">S'inscrire</span></p>
    </div>
  </PageLayout>
);

const About = () => (
  <PageLayout title="À Propos" subtitle="Gastronomie Rapide">
    <div className="max-w-3xl mx-auto bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3rem] text-white text-center shadow-2xl">
      <p className="text-xl leading-relaxed font-medium italic text-gray-200 mb-8">
        FastDélice est né d'une passion simple : offrir une expérience gastronomique haut de gamme sans l'attente interminable. Nous marions la précision du service avec la générosité des saveurs méditerranéennes.
      </p>
      <div className="h-1 w-20 bg-orange-600 mx-auto rounded-full"></div>
    </div>
  </PageLayout>
);

const Menu = ({ categories, addToCart }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedDish, setSelectedDish] = useState(null);
  const navigate = useNavigate();

  const filteredItems = categories.flatMap(cat => 
    cat.dishes.map(dish => ({ ...dish, categoryName: cat.name }))
  ).filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <PageLayout title="La Carte">
      <div className="max-w-xl mx-auto mb-20 relative">
        <input type="text" placeholder="Rechercher une saveur..." className="w-full px-16 py-6 rounded-3xl bg-white/10 backdrop-blur-md border border-white/20 outline-none text-white font-bold" onChange={(e) => setSearchTerm(e.target.value)} />
        <svg className="h-6 w-6 absolute left-6 top-1/2 -translate-y-1/2 text-orange-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {filteredItems.map(item => (
          <div key={item.id} className="group bg-white/10 backdrop-blur-xl border border-white/10 rounded-[3rem] overflow-hidden hover:scale-105 transition duration-500 p-8 text-center text-white relative">
            <div className="text-7xl mb-6 transform group-hover:scale-110 transition duration-500">{item.categoryName.toLowerCase().includes('pizza') ? '🍕' : '🌮'}</div>
            <h3 className="text-2xl font-black italic mb-4 uppercase tracking-tighter">{item.name}</h3>
            <div className="flex justify-between items-center mt-8">
              <span className="text-2xl font-black text-orange-500">{item.price} DH</span>
              <button onClick={() => setSelectedDish(item)} className="bg-white text-black px-6 py-2 rounded-xl font-black text-[10px] uppercase hover:bg-orange-600 hover:text-white transition tracking-widest shadow-lg">Commander</button>
            </div>
          </div>
        ))}
      </div>

      {/* Selection Modal */}
      {selectedDish && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-xl z-[100] flex items-center justify-center p-6">
          <div className="bg-white rounded-[3rem] p-12 max-w-sm w-full text-center shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 bg-orange-600"></div>
            <h3 className="text-3xl font-black mb-8 italic">Votre Mode ?</h3>
            <button onClick={() => {addToCart({...selectedDish, orderType: 'Sur Place'}); setSelectedDish(null); navigate('/panier')}} className="w-full py-5 bg-orange-600 text-white rounded-2xl font-black mb-4 hover:bg-orange-700 transition transform active:scale-95">🍽️ Sur Place</button>
            <button onClick={() => {addToCart({...selectedDish, orderType: 'Emporter'}); setSelectedDish(null); navigate('/panier')}} className="w-full py-5 bg-black text-white rounded-2xl font-black hover:bg-gray-900 transition transform active:scale-95">🥡 À Emporter</button>
            <button onClick={() => setSelectedDish(null)} className="mt-6 text-gray-400 font-bold uppercase text-xs tracking-widest hover:text-red-500 cursor-pointer">Annuler</button>
          </div>
        </div>
      )}
    </PageLayout>
  );
};

const PanierPage = ({ cart }) => (
  <PageLayout title="Récapitulatif" subtitle="Votre commande">
    <div className="max-w-2xl mx-auto bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3rem] text-white shadow-2xl">
      {cart.length === 0 ? (
        <p className="text-center font-black italic opacity-20 text-4xl py-20 uppercase tracking-tighter">Votre panier est vide</p>
      ) : (
        <>
          {cart.map((item, i) => (
            <div key={i} className="flex justify-between items-center py-6 border-b border-white/5 last:border-0">
              <div>
                <h3 className="text-2xl font-black italic">{item.name}</h3>
                <span className="bg-orange-600/20 text-orange-500 text-[9px] uppercase font-black px-2 py-1 rounded-md tracking-widest">{item.orderType}</span>
              </div>
              <span className="text-2xl font-black text-orange-500">{item.price} DH</span>
            </div>
          ))}
          <div className="mt-12 pt-12 border-t-2 border-orange-600 flex justify-between items-center">
            <span className="text-3xl font-black italic tracking-tighter">TOTAL:</span>
            <span className="text-5xl font-black text-orange-500 tracking-tighter">
              {cart.reduce((total, item) => total + parseFloat(item.price), 0).toFixed(2)} DH
            </span>
          </div>
          <button className="w-full mt-12 bg-white text-gray-900 py-6 rounded-2xl font-black text-xl hover:bg-orange-600 hover:text-white transition shadow-2xl uppercase tracking-widest">Confirmer la Commande</button>
        </>
      )}
    </div>
  </PageLayout>
);

// --- MAIN APP COMPONENT ---
// Fixed export to resolve "module has no exports" error
export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    // Fetch data from Django backend
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(err => console.error("API Error:", err));
  }, []);

  const addToCart = (item) => setCart([...cart, item]);

  return (
    <Router>
      <div className="min-h-screen bg-black selection:bg-orange-600 selection:text-white">
        <Navbar cartCount={cart.length} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={addToCart} />} />
          <Route path="/about" element={<About />} />
          <Route path="/panier" element={<PanierPage cart={cart} />} />
